import json
import tempfile
import time

from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class EMServicev1HttpClient(HttpClient):
    """ This class provides a client for the EM Service v1 API. """

    def __init__(self, base_url, connection_alias):
        super(EMServicev1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/emservice/v1"

    def search_parameters_of_current_plan(self, parameter_name, page_number=None, items_per_page=None, **kwargs):
        current_plan_id = self._get_id_of_current_plan()
        endpoint = f"/delta-plans/{current_plan_id}/parameters"
        parameters = {
                      "filterByText": parameter_name,
                      "itemsPerPage": items_per_page,
                      "pageNumber": page_number
                  }

        payload = {key: value for key, value in parameters.items() if value is not None}

        return self._send_post_request(endpoint=endpoint, json=payload)

    def get_staged_plans(self):
        return self._send_get_request(endpoint="/staged-plans")

    def plan_validation(self, plan_id):
        endpoint = f"/staged-plans/{plan_id}/actions/validations"
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_post_request(endpoint=endpoint, headers=headers)

    def get_operation_state_of_validating_plan(self, plan_id, operation_id, timeout=30):
        endpoint = f"/staged-plans/{plan_id}/actions/validations/{operation_id}"
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)

    def download_staged_plan_file(self, plan_id, include_auto_config_data=False):
        headers = {
            "Content-Type": "application/json",
        }
        payload= {
            "deltaChangeOnly": True,
            "includeAutoConfigData": include_auto_config_data
        }
        action_id = self._send_post_request(endpoint=f"/staged-plans/{plan_id}/actions/uploads",
                                            headers=headers, data=json.dumps(payload))["actionId"]
        time.sleep(5)   #reason: wait for staged plan upload operation success
        file_name = self._send_get_request(endpoint=f"/staged-plans/{plan_id}/actions/uploads/{action_id}")["fileName"]

        return self._save_to_temporary_file_and_get_path(self._send_get_request(endpoint=f"/files/{file_name}",
                                                                                headers=headers))

    def get_validation_result_of_staged_plan(self, plan_id, validation_id, error_type):
        endpoint = f"/staged-plans/{plan_id}/validation-results/{validation_id}"
        headers = {
            "Content-Type": "application/json",
        }

        payload = {
            "filterByValidationErrorType": error_type
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, payload=payload, timeout=30)

    def fix_plan_validation_errors(self, plan_id, add_missing_objects, timeout=30):
        endpoint = f"/staged-plans/{plan_id}/actions/fix"
        headers = {
            "Content-Type": "application/json",
        }

        payload = {"addMissingObjects": add_missing_objects, "deltaValidationNeeded": True}

        return self._send_post_request(endpoint=endpoint, headers=headers, json=payload, timeout=timeout)

    def get_action_state_of_fix_plan(self, plan_id, action_id):
        endpoint = f"/staged-plans/{plan_id}/actions/fix/{action_id}"
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers)

    @staticmethod
    def _save_to_temporary_file_and_get_path(file):
        temp_file = tempfile.NamedTemporaryFile(delete=False)
        temp_file.write(file)
        temp_file.close()

        return temp_file.name

    def _get_id_of_current_plan(self):
        """
        Due to changes with CB012840, current plan info is available in /delta-plans endpoint.
        """
        current_plans_info = self._send_get_request(endpoint="/delta-plans")

        for plan in current_plans_info:
            if plan["planName"] == "Current Plan":
                return plan["planId"]
